import manifest from "../data/image-manifest.json";

// Static export serves files as-is, so responsive variants are pre-generated by
// scripts/optimize-images.cjs and described in data/image-manifest.json.
// srcset entries must be URL-encoded: an unencoded space ends the URL in srcset.
function srcSet(src, extension) {
  const entry = manifest[src];
  const base = src.replace(/\.webp$/, "");
  const candidates = entry.widths.map((width) => `${encodeURI(`${base}-${width}w.${extension}`)} ${width}w`);
  candidates.push(`${encodeURI(`${base}.${extension}`)} ${entry.width}w`);
  return candidates.join(", ");
}

/**
 * Drop-in replacement for the next/image props this site uses (`fill`, `sizes`, `loading`,
 * `fetchPriority`), rendering <picture> with AVIF + WebP sources.
 */
export default function OptimizedImage({ src, alt, width, height, fill = false, sizes = "100vw", loading = "lazy", fetchPriority, className, style, ...props }) {
  const entry = manifest[src];
  const fillStyle = fill ? { position: "absolute", inset: 0, width: "100%", height: "100%" } : undefined;
  const image = (
    <img
      src={encodeURI(src)}
      srcSet={entry ? srcSet(src, "webp") : undefined}
      sizes={entry ? sizes : undefined}
      alt={alt}
      width={fill ? undefined : width ?? entry?.width}
      height={fill ? undefined : height ?? entry?.height}
      loading={loading}
      fetchPriority={fetchPriority}
      decoding={loading === "eager" ? undefined : "async"}
      className={className}
      style={fillStyle || style ? { ...fillStyle, ...style } : undefined}
      {...props}
    />
  );
  if (!entry) return image;
  return (
    <picture className="contents">
      <source type="image/avif" srcSet={srcSet(src, "avif")} sizes={sizes} />
      {image}
    </picture>
  );
}
